const rows = $input.all().map((i) => i.json);
const now = new Date().toISOString();
return [{ json: {
  notifications: rows.map((r) => ({
    kind: 'stuck_draft', severity: 'warning', title: 'Claim awaiting doctor review',
    message: `Claim ${r.claim_id} has been awaiting doctor review for ${Math.round(r.age_hours)} hours.`,
    claim_id: r.claim_id, ref_id: r.doctor_id,
  })),
  audit_rows: rows.map((r) => ({
    ts: now, actor: 'Workflow Engine', actor_type: 'system', event: 'Stuck draft reminder sent',
    entity: `Claim ${r.claim_id}`, claim_id: r.claim_id, visit_id: null, patient_id: null, code: null,
    previous_value: null, new_value: null, run_id: 'cron_stuck_draft', version: null,
    metadata: { review_age_hours: String(Math.round(r.age_hours)) },
  })),
} }];
